resources.string:
"#version 300 es\n"

uniform mat4 uMVPMatrix;
uniform float wave;
uniform vec3 position[256];
uniform vec3 eyePosition;
in vec4 vPosition;
in vec3 vNormal;
in vec2 a_TexCoordinate;
out vec2 texCoord;
out vec2 texCoordPosition;
out float fogFactor;

void main() {


    vec4 outPos = vPosition;
    outPos.xyz = outPos.xyz + position[gl_InstanceID];

    float winter = sin( wave + outPos.x + outPos.z + float(gl_InstanceID) );

    outPos.x = outPos.x + winter * 0.3 * vPosition.y;
    outPos.y = outPos.y - abs(winter * 0.15 * vPosition.y);

    texCoordPosition.y = outPos.z / 40.0;
    texCoordPosition.x = outPos.x / 40.0;

    fogFactor = min(1.0, distance(eyePosition, outPos.xyz) * 0.03);

    gl_Position = uMVPMatrix * vec4(outPos.xyz, 1.0);

    texCoord = a_TexCoordinate;
}

"#version 300 es\n"

precision mediump float;

uniform sampler2D u_Texture;
uniform sampler2D shadowTexture;
in vec2 texCoord;
in vec2 texCoordPosition;
in float fogFactor;

out vec4 fragColor;

void main() {

vec4 color = texture(u_Texture, texCoord);

if(color.a<0.5){
    discard;
}

color = color * texture(shadowTexture, texCoordPosition);

float fogFixed = max(fogFactor, 0.75);
fogFixed = fogFixed - 0.75;
fogFixed = fogFixed * 4.0;

color = mix(color, vec4(0.5, 0.7, 1.0, 1.0), fogFixed);

fragColor = color;
}
